{"question": "Quy trình điều trị cụ thể cho bệnh viêm tuyến nước bọt dưới hàm do sỏi bao gồm bước nào đối với vùng phẫu thuật?", "claim": "Trong phẫu thuật lấy sỏi và cắt bỏ tuyến dưới hàm, quy trình điều trị cụ thể yêu cầu phải thực hiện kiểm soát vùng phẫu thuật.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ điều trị viêm tuyến nước bọt dưới hàm do sỏi có đề cập đến phẫu thuật lấy sỏi và cắt bỏ tuyến dưới hàm, bao gồm yêu cầu kiểm soát vùng phẫu thuật."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "1.Tiên lượng Phẫu thuật cắt bỏ nang khe mang, nếu thực hiện đúng kỹ thuật thì đều cho kết quả tốt, không tái phát."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Kiểm soát vùng phẫu thuật."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["28. NANG KHE MANG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["44. VIÊM TUYẾ N NƯỚ C BỌ T DƯỚI HÀM DO SỎ I", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "b. Phẫu thuật lấy sỏi và cắt bỏ tuyến dưới hàm"]}]}
