{"question": "Phương pháp điều trị cụ thể đối với bệnh viêm tuyến nước bọt dưới hàm do sỏi bao gồm những gì?", "claim": "Điều trị cụ thể viêm tuyến nước bọt dưới hàm do sỏi bao gồm phẫu thuật bộc lộ và lấy sỏi để bảo tồn tuyến.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu chuyên khoa ghi nhận phương pháp phẫu thuật bộc lộ và lấy sỏi nhằm bảo tồn tuyến nước bọt dưới hàm bị viêm do sỏi."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Là tình trạng tổn thương viêm tuyến nước bọt có nguyên nhân do sỏi có thể ở vùng tuyến hoặc ống tuyến."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Bộc lộ và lấy sỏi."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["44. VIÊM TUYẾ N NƯỚ C BỌ T DƯỚI HÀM DO SỎ I", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["44. VIÊM TUYẾ N NƯỚ C BỌ T DƯỚI HÀM DO SỎ I", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "a. Phẫu thuật lấy sỏi và điều trị bảo tồn tuyến"]}]}
