{"question": "Triệu chứng lâm sàng tại chỗ của áp xe vùng mang tai có thể xuất hiện biểu hiện nào ở vùng thành bên hầu?", "claim": "Bệnh nhân bị áp xe vùng mang tai tuyệt đối không bao giờ có triệu chứng sưng sau trụ thành bên hầu.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu giải phẫu hệ thống nhai mô tả đường nối hai cực lồi cầu kéo dài về phía trong và sau, gặp nhau ở vùng bờ trước lỗ chẩm."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Nang khe mang được hình thành do sự vùi kẹt của biểu mô. Nang thường nằm ở vùng cổ bên sát bờ trước cơ ức đòn chũm."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Có thể có sưng sau trụ thành bên hầu."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["28. NANG KHE MANG", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["33. ÁP XE VÙNG MANG TAI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
