{"question": "Dụng cụ cần thiết trong phong bế dây thần kinh cằm bao gồm những loại thuốc mỡ và ống tiêm nào?", "claim": "Khi thực hiện phong bế dây thần kinh cằm, cần chuẩn bị thuốc mỡ tại chỗ như lidocaine 5% hoặc benzocaine 20% và ống tiêm hút dịch nha khoa có nòng hẹp.", "internal_evidence": [{"evidence_id": "I1", "content": "Chương 3 bàn về khái niệm khớp cắn và lý thuyết của Bonwill mô tả hàm dưới như một tam giác đều 10cm với 3 đỉnh là hai lồi cầu và góc cắn gần của răng cửa giữa dưới."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Ghi lại bất kỳ khiếm khuyết thần kinh nào có từ trước trước khi tiến hành phong bế dây thần kinh."}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Có thể sử dụng phương pháp tiếp cận trong miệng hoặc ngoài miệng tới lỗ cằm. Cách tiếp cận trong miệng, được ưa thích và thảo luận ở đây, gây đau ít hơn cách tiếp cận ngoài cơ thể."}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Phong bế dây thần kinh có thể không hiệu quả nếu thuốc gây tê không được đưa vào đủ gần dây thần kinh đó."}, {"quote_id": "P1.Q4", "evidence_id": "P1", "text": "Sử dụng kim mới cho mỗi lần tiêm (kim trước đó có thể bị mô hoặc máu chặn lại, làm che khuất vị trí tiêm vào mạch máu)."}, {"quote_id": "P1.Q5", "evidence_id": "P1", "text": "Dừng thủ thuật phong bế dây thần kinh và sử dụng phương pháp gây mê khác nếu quý vị không chắc kim ở đâu hoặc nếu bệnh nhân không hợp tác."}, {"quote_id": "P2.Q6", "evidence_id": "P2", "text": "Thuốc mỡ tại chỗ* (ví dụ, lidocaine 5%, benzocaine 20%)"}, {"quote_id": "P2.Q7", "evidence_id": "P2", "text": "Tiêm thuốc tê tại chỗ như lidocaine 2% có hoặc không có epinephrine† 1:100.000, hoặc để gây tê trong thời gian dài hơn, bupivacaine 0,5% có hoặc không có epinephrine† 1:200.000"}, {"quote_id": "P2.Q8", "evidence_id": "P2", "text": "Ống tiêm hút dịch nha khoa (có nòng hẹp và hộp thuốc gây tê tiêm tùy chỉnh) hoặc ống tiêm nòng hẹp khác (ví dụ: 3 mL) có chốt khóa"}, {"quote_id": "P2.Q9", "evidence_id": "P2", "text": "Kim 25 hoặc 27 gauge: dài 3 cm đối với các trường hợp phong bế dây thần kinh"}], "public_sources": [{"evidence_id": "P1", "title": "Cách thực hiện phong bế dây thần kinh cằm", "heading_path": ["Những cân nhắc bổ sung trong phong bế dây thần kinh cằm"]}, {"evidence_id": "P2", "title": "Cách thực hiện phong bế dây thần kinh cằm", "heading_path": ["Dụng cụ trong phong bế dây thần kinh cằm"]}]}
