{"question": "Dấu hiệu lâm sàng tại chỗ của khối áp xe vùng cơ cắn ở vị trí nông nằm trên cơ cắn là gì?", "claim": "Nếu khối áp xe nằm ở vị trí nông và ở trên cơ cắn, khi thăm khám có thể sờ thấy dấu hiệu chuyển sóng.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận trường hợp áp xe vùng cơ cắn nông nằm trên cơ cắn, bác sĩ khám thực thể có thể phát hiện dấu hiệu chuyển sóng rõ rệt."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Vùng cơ cắn có 1 khối sưng lớn, da trên khối sưng nóng đỏ hoặc tím, căng, nề, có thể thâm nhiễm lan rộng lên trên đến mi mắt dưới hoặc hố thái dương, ra sau tới vùng mang tai, xuống dưới tới vùng dưới hàm. Các rãnh tự nhiên trên mặt bị xóa."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Nếu khối áp xe ở vị trí nông, nằm trên cơ cắn có thể sờ thấy dấu hiệu chuyển sóng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["29. ÁP XE VÙNG CƠ CẮN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["29. ÁP XE VÙNG CƠ CẮN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
